// Identity policy attached to the Glue job's IAM role (least privilege)
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "ReadBronzePrefixOnly",
      "Effect": "Allow",
      "Action": ["s3:GetObject", "s3:ListBucket"],
      "Resource": [
        "arn:aws:s3:::acme-datalake-prod",
        "arn:aws:s3:::acme-datalake-prod/bronze/*"
      ],
      "Condition": {
        "StringEquals": { "s3:prefix": ["bronze/", "bronze/*"] }
      }
    },
    {
      "Sid": "UseKmsForDecryption",
      "Effect": "Allow",
      "Action": ["kms:Decrypt", "kms:GenerateDataKey"],
      "Resource": "arn:aws:kms:us-east-1:123456789012:key/abcd-1234"
    }
  ]
}

// Resource policy on the bucket: enforce TLS + restrict to the VPC endpoint
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "DenyInsecureTransport",
      "Effect": "Deny",
      "Principal": "*",
      "Action": "s3:*",
      "Resource": [
        "arn:aws:s3:::acme-datalake-prod",
        "arn:aws:s3:::acme-datalake-prod/*"
      ],
      "Condition": { "Bool": { "aws:SecureTransport": "false" } }
    },
    {
      "Sid": "OnlyFromOurVpcEndpoint",
      "Effect": "Deny",
      "Principal": "*",
      "Action": "s3:*",
      "Resource": "arn:aws:s3:::acme-datalake-prod/*",
      "Condition": {
        "StringNotEquals": { "aws:SourceVpce": "vpce-0abc123def4567890" }
      }
    }
  ]
}
